+namespace CheckoutPricing.Domain;
+
+public static class PromoDiscountPolicy
+{
+    private const int Welcome5Cents = 500;
+    private const int Summer10CapCents = 1_500;
+
+    public static int PromoPartCents(string? promoCode, int subtotalCents, int loyaltyPartCents)
+    {
+        if (string.Equals(promoCode, "WELCOME5", StringComparison.OrdinalIgnoreCase))
+        {
+            return Welcome5Cents;
+        }
+
+        if (string.Equals(promoCode, "SUMMER10", StringComparison.OrdinalIgnoreCase))
+        {
+            return Math.Min(Summer10CapCents, (subtotalCents - loyaltyPartCents) / 10);
+        }
+
+        return 0;
+    }
+}

